    "Read only": "\u0422\u0456\u043B\u044C\u043A\u0438 \u0434\u043B\u044F \u0447\u0438\u0442\u0430\u043D\u043D\u044F",
    "Argo CD applications": "\u041F\u0440\u043E\u0433\u0440\u0430\u043C\u0438 Argo CD",
    "Language": "\u041C\u043E\u0432\u0430",
    "Follow host": "\u0421\u043B\u0456\u0434\u043A\u0443\u0439\u0442\u0435 \u0437\u0430 \u0445\u043E\u0441\u0442\u043E\u043C",
    "Density": "\u0429\u0456\u043B\u044C\u043D\u0456\u0441\u0442\u044C",
